function detectClient(text) {
  const t = (text || '').toLowerCase();
  if (t.includes('rosario') || t.includes('urosario')) return 'rosario';
  if (t.includes('usmp') || t.includes('san martin')) return 'usmp';
  return null;
}

const COLUMN_ALIASES = {
  keyword: ['Keyword', 'Phrase', 'Palabra clave', 'Ph', 'Query'],
  volumen: ['Volume', 'Search Volume', 'Avg. monthly searches', 'Volumen', 'Volumen de busqueda', 'Nq', 'Monthly Searches', 'Vol.'],
  kd: ['Keyword Difficulty', 'KD', 'Keyword Difficulty Index', 'Difficulty', 'Dificultad', 'Kd', 'KD %'],
  cpc: ['CPC', 'CPC (USD)', 'Cp'],
  competition: ['Competition', 'Competition Density', 'Competencia', 'Co'],
  intent: ['Intent', 'Search Intent', 'Intencion'],
  serp: ['SERP Features', 'SERP', 'SERP Features by Keyword'],
};

function detectDelimiter(line) {
  const s = (line.match(/;/g) || []).length;
  const c = (line.match(/,/g) || []).length;
  const t = (line.match(/\t/g) || []).length;
  if (t > s && t > c) return '\t';
  return s > c ? ';' : ',';
}

function parseCSV(content, delim) {
  if (content.charCodeAt(0) === 0xFEFF) content = content.slice(1);
  const rows = [];
  let row = []; let f = ''; let inQ = false;
  for (let i = 0; i < content.length; i++) {
    const c = content[i];
    if (inQ) {
      if (c === '"' && content[i + 1] === '"') { f += '"'; i++; }
      else if (c === '"') inQ = false;
      else f += c;
    } else {
      if (c === '"') inQ = true;
      else if (c === delim) { row.push(f); f = ''; }
      else if (c === '\n' || c === '\r') {
        if (c === '\r' && content[i + 1] === '\n') i++;
        if (f !== '' || row.length > 0) { row.push(f); rows.push(row); }
        row = []; f = '';
      } else f += c;
    }
  }
  if (f !== '' || row.length > 0) { row.push(f); rows.push(row); }
  if (rows.length < 2) return [];
  const headers = rows[0].map((h) => h.trim());
  return rows.slice(1).map((r) => {
    const obj = {};
    headers.forEach((h, idx) => { obj[h] = (r[idx] || '').trim(); });
    return obj;
  });
}

function findCol(headers, aliases) {
  const low = headers.map((h) => String(h).toLowerCase());
  for (const a of aliases) {
    const i = low.indexOf(a.toLowerCase());
    if (i >= 0) return headers[i];
  }
  for (const a of aliases) {
    const f = headers.find((h) => String(h).toLowerCase().includes(a.toLowerCase()));
    if (f) return f;
  }
  return null;
}

function parseNum(raw) {
  if (raw == null || raw === '') return null;
  const s = String(raw).replace(/[^0-9.,-]/g, '');
  if (!s) return null;
  let n;
  if (s.includes('.') && s.includes(',')) n = s.replace(/,/g, '');
  else if (s.includes(',') && !s.includes('.')) {
    n = /,\d{3}$/.test(s) ? s.replace(/,/g, '') : s.replace(',', '.');
  } else n = s;
  const r = parseFloat(n);
  return isNaN(r) ? null : r;
}

/**
 * prefilterRows: dado un array de rows (cada una un objeto con header→value),
 * mapea a la estructura común (keyword, volumen, kd, ...) y aplica filtros.
 */
function prefilterRows(rows, opts) {
  const minVolume = opts.minVolume ?? 30;
  const maxKd = opts.maxKd ?? 60;
  const maxResults = opts.maxResults ?? 30;
  if (!rows.length) return { candidates: [], stats: { rowsRead: 0, dropped: { volume: 0, kd: 0, dup: 0, missing: 0 } } };

  const headers = Object.keys(rows[0]);
  const cols = {
    keyword: findCol(headers, COLUMN_ALIASES.keyword),
    volumen: findCol(headers, COLUMN_ALIASES.volumen),
    kd: findCol(headers, COLUMN_ALIASES.kd),
    cpc: findCol(headers, COLUMN_ALIASES.cpc),
    intent: findCol(headers, COLUMN_ALIASES.intent),
    serp: findCol(headers, COLUMN_ALIASES.serp),
  };

  const map = new Map();
  const stats = { rowsRead: 0, dropped: { volume: 0, kd: 0, dup: 0, missing: 0 } };
  if (!cols.keyword) return { candidates: [], stats, columnMapping: cols };

  for (const row of rows) {
    stats.rowsRead++;
    const raw = row[cols.keyword];
    if (raw === null || raw === undefined || raw === '') { stats.dropped.missing++; continue; }
    const rawStr = String(raw);
    const key = rawStr.toLowerCase().trim().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ');
    if (!key) { stats.dropped.missing++; continue; }
    const vol = cols.volumen ? Math.round(parseNum(row[cols.volumen]) || 0) : 0;
    const kd = cols.kd ? parseNum(row[cols.kd]) : null;
    if (vol < minVolume) { stats.dropped.volume++; continue; }
    if (kd !== null && kd > maxKd) { stats.dropped.kd++; continue; }
    const exist = map.get(key);
    if (exist) {
      stats.dropped.dup++;
      if (exist.volumen >= vol) continue;
    }
    map.set(key, {
      keyword: rawStr.trim(),
      volumen: vol,
      kd: kd !== null ? Math.round(kd * 10) / 10 : null,
      cpc: cols.cpc ? parseNum(row[cols.cpc]) : null,
      intent: cols.intent ? String(row[cols.intent] || '').trim() || null : null,
      serp: cols.serp ? String(row[cols.serp] || '').trim() || null : null,
    });
  }
  const sorted = Array.from(map.values()).sort((a, b) =>
    b.volumen - a.volumen || (a.kd ?? 999) - (b.kd ?? 999)
  );
  return { candidates: sorted.slice(0, maxResults), stats, columnMapping: cols };
}

