// Entry point — recoge data de DOS fuentes
// ============================================================

// 1) Datos del Chat Trigger (chatInput + binarios CSV)
const chatTrigger = $('Chat Trigger').first();
const chatInput =
  chatTrigger.json?.chatInput ||
  chatTrigger.json?.message ||
  chatTrigger.json?.input ||
  '';

const triggerFiles = chatTrigger.json?.files || [];

// 2) Cosechar TODAS las filas:
//    - Si Extract from File procesó XLSX, $input.all() contiene items con row data
//    - Para CSVs en binary, parseamos inline aquí
const allRows = [];
const sourceCSVs = [];
const sourceXLSX = [];

// 2a) Filas extraídas por el nodo Extract from File (XLSX)
for (const item of $input.all()) {
  // Una row típica de Extract from File se ve como:
  //   { json: { Keyword: '...', Volume: 123, ... } }
  // Una row de fallback (cuando Extract falló) se ve como:
  //   { json: { chatInput: '...', files: [...] } } — la del trigger pasada
  // Detectamos: si tiene la columna 'Keyword' o similar, es row de XLSX
  if (item.json && (item.json.Keyword || item.json.Phrase || item.json['Search Volume'] || item.json.Volume || item.json.Nq)) {
    allRows.push(item.json);
  }
}
if (allRows.length > 0) {
  sourceXLSX.push({ rows: allRows.length });
}

// 2b) Parsear CSVs del binary del Chat Trigger
if (chatTrigger.binary) {
  for (const [field, bin] of Object.entries(chatTrigger.binary)) {
    const fname = String(bin.fileName || field).toLowerCase();
    const mime = String(bin.mimeType || '').toLowerCase();
    const isCSV = fname.endsWith('.csv') || fname.endsWith('.txt') || mime === 'text/csv' || mime === 'text/plain';
    if (isCSV && bin.data) {
      const buf = Buffer.from(bin.data, 'base64');
      let content = buf.toString('utf-8');
      if (content.includes('�')) content = buf.toString('latin1');
      const firstLine = content.split('\n')[0] || '';
      const delim = detectDelimiter(firstLine);
      const rows = parseCSV(content, delim);
      sourceCSVs.push({ name: bin.fileName || field, rows: rows.length });
      for (const r of rows) allRows.push(r);
    }
  }
}

// 3) Aplicar prefilter sobre TODO el pool unificado
const filtered = prefilterRows(allRows, {});

// 4) Detectar cliente
const clientKey = detectClient(chatInput);
const clientConfig = clientKey ? CLIENTES[clientKey] : null;

// 5) Output
return [{
  json: {
    chatInput,
    fecha_analisis: new Date().toISOString().split('T')[0],
    cliente_detectado: clientKey,
    cliente_config: clientConfig,
    total_rows_received: allRows.length,
    sources: {
      csv_files: sourceCSVs,
      xlsx_files: sourceXLSX,
      trigger_files: triggerFiles.map((f) => ({ name: f.fileName, ext: f.fileExtension, size: f.fileSize })),
    },
    shortlist_kws: filtered.candidates,
    prefilter_stats: filtered.stats,
    column_mapping: filtered.columnMapping,
    has_data: allRows.length > 0,
    has_client: clientConfig !== null,
  },
}];

